/* From Uiverse.io by sameer2malik - Tags: neumorphism, instagram, form */
.__UIV_SCOPE__ .container {
  height: 100%;
  width: 100%;
}

.__UIV_SCOPE__ .hero {
  padding: 60px 20px;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f7f7f7;
}

.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

.__UIV_SCOPE__ .input {
  padding: 1rem 1.2rem;
  margin: 1rem;
  border-radius: 2rem;
  display: block;
  width: 80%;
  border: none;
  box-shadow: inset 6px 6px 8px rgba(97, 97, 97, 0.075),
    6px 6px 6px rgba(255, 255, 255, 0.781);
  outline: none;
  background-color: inherit;
  color: rgb(161, 161, 161);
  font-size: inherit;
}

.__UIV_SCOPE__ .submit, .__UIV_SCOPE__ .btn {
  margin-top: 20px;
  font-weight: bold;
  box-shadow: -3px -3px 5px white, 3px 3px 5px rgba(209, 209, 209, 0.705);
  color: rgb(112, 112, 112);
  cursor: pointer;
}

.__UIV_SCOPE__ .btn {
  text-align: center;
  color: black;
}

.__UIV_SCOPE__ .logo {
  font-size: 3rem;
  color: black;
  font-weight: 600;
  margin: 30px;
}

.__UIV_SCOPE__ ::placeholder {
  color: rgb(161, 161, 161);
}

.__UIV_SCOPE__ .forgotten {
  text-align: center;
  font-size: .8rem;
  width: 80%;
  color: gray;
  margin: 15px 0;
}

.__UIV_SCOPE__ a {
  color: inherit;
  font-weight: bold;
  text-decoration: none;
}

.__UIV_SCOPE__ .or {
  position: relative;
  font-weight: bold;
  color: rgb(112, 112, 112);
}

.__UIV_SCOPE__ .or::before, .__UIV_SCOPE__ .or::after {
  position: absolute;
  content: '';
  width: 700%;
  height: 1px;
  top: 50%;
  margin: 0 6px;
  background-color: rgba(0, 0, 0, 0.479);
}

.__UIV_SCOPE__ .or::before {
  right: 100%;
}

.__UIV_SCOPE__ .or::after {
}

.__UIV_SCOPE__ .signup {
  color: gray;
  margin-top: 15px;
  font-size: 1rem;
}
